def two_sum(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        need = target - v
        if need in seen:
            return [seen[need], i]
        seen[v] = i
    return []

def max_profit(prices):
    best, min_p = 0, float('inf')
    for p in prices:
        min_p = min(min_p, p)
        best = max(best, p - min_p)
    return best

def max_subarray(nums):
    cur = best = nums[0]
    for v in nums[1:]:
        cur = max(v, cur + v)
        best = max(best, cur)
    return best

def contains_duplicate(nums):
    seen = set()
    for v in nums:
        if v in seen:
            return True
        seen.add(v)
