import heapq
def find_kth_largest(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)
    for v in nums[k:]:
        if v > heap[0]:
            heapq.heapreplace(heap, v)
    return heap[0]

from collections import deque
def oranges_rotting(grid):
    rows, cols = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                q.append((r, c, 0))
            elif grid[r][c] == 1:
                fresh += 1
    minutes = 0
    while q:
        r, c, t = q.popleft()
        minutes = max(minutes, t)
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                grid[nr][nc] = 2
                fresh -= 1
                q.append((nr, nc, t + 1))
    return minutes if fresh == 0 else -1

def generate_parenthesis(n):
    res = []
    def backtrack(s, o, c):
        if len(s) == 2 * n:
            res.append(s)
            return
        if o < n:
            backtrack(s + '(', o + 1, c)
        if c < o:
            backtrack(s + ')', o, c + 1)
    backtrack('', 0, 0)
    return res

def climb_stairs(n):
    if n <= 2:
