def max_profit(prices):
    best, min_p = 0, float('inf')
    for p in prices:
        min_p = min(min_p, p)
        best = max(best, p - min_p)
    return best

def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

def max_area(height):
    lo, hi = 0, len(height) - 1
    best = 0
    while lo < hi:
        area = min(height[lo], height[hi]) * (hi - lo)
        best = max(best, area)
        if height[lo] < height[hi]:
            lo += 1
        else:
            hi -= 1
    return best

def length_of_longest_substring(s):
    seen = set()
    lo = best = 0
    for hi, ch in enumerate(s):
        while ch in seen:
            seen.remove(s[lo])
            lo += 1
        seen.add(ch)
        best = max(best, hi - lo + 1)
    return best

def min_window(s, t):
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    have = {}
    formed = 0
    lo, min_len, start = 0, float('inf'), 0
    for hi, ch in enumerate(s):
        have[ch] = have.get(ch, 0) + 1
        if ch in need and have[ch] == need[ch]:
            formed += 1
        while formed == len(need):
            if hi - lo + 1 < min_len:
                min_len = hi - lo + 1
                start = lo
            have[s[lo]] -= 1
            if s[lo] in need and have[s[lo]] < need[s[lo]]:
                formed -= 1
            lo += 1
    return s[start:start + min_len] if min_len != float('inf') else ''

from collections import deque
def max_sliding_window(nums, k):
    dq = deque()
    out = []
    for i, v in enumerate(nums):
        if dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] <= v:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

import heapq
def find_kth_largest(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)
    for v in nums[k:]:
        if v > heap[0]:
            heapq.heapreplace(heap, v)
    return heap[0]

def generate_parenthesis(n):
    res = []
    def backtrack(s, o, c):
        if len(s) == 2 * n:
            res.append(s)
            return
        if o < n:
            backtrack(s + '(', o + 1, c)
        if c < o:
            backtrack(s + ')', o, c + 1)
    backtrack('', 0, 0)
    return res

import bisect
def length_of_lis(nums):
    tails = []
    for v in nums:
        i = bisect.bisect_left(tails, v)
        if i == len(tails):
            tails.append(v)
        else:
            tails[i] = v
    return len(tails)

def longest_common_subsequence(text1, text2):
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i-1] == text2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for v in nums:
        for s in range(target, v - 1, -1):
            dp[s] = dp[s] or dp[s - v]
    return dp[target]

def longest_palindrome(s):
    def expand(lo, hi):
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return s[lo+1:hi]
    best = ''
    for i in range(len(s)):
        best = max(best, expand(i, i), expand(i, i + 1), key=len)
    return best
